"""Independent tests for reduce.py: 3-SAT -> Dominating Set.

We implement our own brute-force solvers for both problems from the
definitions in problems.py, then compare the answers of many small source
instances with the answers of their reductions.
"""

from __future__ import annotations

import itertools
import json
import random

from problems import ThreeSat, DominatingSet
from reduce import reduce


# ----------------------------------------------------------------------
# Brute-force solvers written from the problem definitions.

def brute_sat(instance):
    """Return True iff the 3-SAT instance is satisfiable."""
    ThreeSat.validate(instance)
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        good = True
        for clause in clauses:
            sat = False
            for lit in clause:
                val = bits[abs(lit) - 1]
                if (lit > 0 and val) or (lit < 0 and not val):
                    sat = True
                    break
            if not sat:
                good = False
                break
        if good:
            return True
    return False


def brute_ds(instance):
    """Return True iff the graph has a dominating set of size at most k."""
    DominatingSet.validate(instance)
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for size in range(0, k + 1):
        for comb in itertools.combinations(range(n), size):
            dominated = set(comb)
            for v in comb:
                dominated |= adj[v]
            if len(dominated) == n:
                return True
    return False


# ----------------------------------------------------------------------
# Instance generation.

def all_clauses(m):
    """All valid 3-literal clauses over variables 1..m."""
    clauses = []
    for vars_ in itertools.combinations(range(1, m + 1), 3):
        for signs in itertools.product([1, -1], repeat=3):
            clauses.append([s * v for s, v in zip(signs, vars_)])
    return clauses


def random_instance(rng, m, max_clauses, allow_dupes=True):
    pool = all_clauses(m)
    if not pool:
        return {"num_vars": m, "clauses": []}
    c = rng.randint(0, max_clauses)
    clauses = []
    for _ in range(c):
        clauses.append(list(rng.choice(pool)))
        if not allow_dupes and len(clauses) > 1 and clauses[-1] in clauses[:-1]:
            clauses.pop()
    return {"num_vars": m, "clauses": clauses}


# ----------------------------------------------------------------------
# Test driver.

def main():
    rng = random.Random(12345)
    tests_run = 0
    tests_passed = 0
    mismatches = []

    def check(inst):
        nonlocal tests_run, tests_passed
        tests_run += 1
        src_ans = brute_sat(inst)
        try:
            red = reduce(inst)
        except Exception as exc:  # reduction must not crash on valid input
            mismatches.append((inst, "reduce raised %r" % (exc,)))
            return
        # target must be a valid DominatingSet instance
        try:
            DominatingSet.validate(red)
        except Exception as exc:
            mismatches.append((inst, "invalid target %r" % (exc,)))
            return
        tgt_ans = brute_ds(red)
        if src_ans == tgt_ans:
            tests_passed += 1
        else:
            mismatches.append((inst, src_ans, tgt_ans, red))

    # 1) Edge cases: m = 0, 1, 2 with no clauses (only valid form).
    for m in (0, 1, 2, 3):
        check({"num_vars": m, "clauses": []})

    # 2) Exhaustive over all 256 formulas with m = 3.
    pool3 = all_clauses(3)
    for r in range(len(pool3) + 1):
        for subset in itertools.combinations(range(len(pool3)), r):
            check({"num_vars": 3, "clauses": [list(pool3[i]) for i in subset]})

    # 3) Random formulas for m = 3, 4, 5 (and a few 6).
    for m in (3, 4, 5):
        for _ in range(400):
            check(random_instance(rng, m, max_clauses=8))
    for _ in range(60):
        check(random_instance(rng, 6, max_clauses=12))

    # 4) Duplicated clauses.
    for _ in range(200):
        m = rng.randint(3, 5)
        inst = random_instance(rng, m, max_clauses=6)
        if inst["clauses"]:
            inst["clauses"].append(list(rng.choice(inst["clauses"])))
        check(inst)

    print("tests_run   =", tests_run)
    print("tests_passed=", tests_passed)
    print("mismatches  =", len(mismatches))
    for mm in mismatches[:5]:
        print("MISMATCH:", mm)

    verified = (tests_run == tests_passed) and (tests_run > 0)
    with open("verdict.json", "w") as fh:
        json.dump(
            {"verified": bool(verified), "tests_run": tests_run,
             "tests_passed": tests_passed},
            fh,
        )
    print("verdict:", {"verified": bool(verified), "tests_run": tests_run,
                       "tests_passed": tests_passed})


if __name__ == "__main__":
    main()
