import itertools, random
from test_reduce import brute_sat, brute_ds
from reduce import reduce

rng = random.Random(7)
pool = [[s*v for s,v in zip(sg, vs)] for vs in itertools.combinations(range(1,5),3) for sg in itertools.product([1,-1],repeat=3)]

def bad(inst):
    return (not brute_sat(inst)) and brute_ds(reduce(inst))

# collect mismatches, then minimize
mismatches=[]
for _ in range(20000):
    c = rng.randint(1, 12)
    inst={"num_vars":4,"clauses":[list(rng.choice(pool)) for _ in range(c)]}
    if bad(inst):
        mismatches.append(inst)
    if len(mismatches)>=30: break

print("found mismatches:", len(mismatches))
# minimize each by removing clauses while still bad
best=None
for inst in mismatches:
    clauses=[list(c) for c in inst["clauses"]]
    changed=True
    while changed:
        changed=False
        for i in range(len(clauses)):
            trial={"num_vars":4,"clauses":clauses[:i]+clauses[i+1:]}
            if trial["clauses"] and bad(trial):
                clauses=trial["clauses"]; changed=True; break
    cand={"num_vars":4,"clauses":clauses}
    if best is None or len(clauses)<len(best["clauses"]):
        best=cand
    print("minimized size", len(clauses), "sat", brute_sat(cand), "ds", brute_ds(reduce(cand)))

print("BEST:", best)
print("sat =", brute_sat(best))
red=reduce(best)
print("red n,k =", red["n"], red["k"])
print("ds =", brute_ds(red))
